import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.Brv5O9VI.js";const m=JSON.parse('{"title":"Step 12: Technical & Regulatory Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),i={name:"11-glossary.md"};function o(s,e,l,c,d,g){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="step-12-technical-regulatory-glossary" tabindex="-1">Step 12: Technical &amp; Regulatory Glossary <a class="header-anchor" href="#step-12-technical-regulatory-glossary" aria-label="Permalink to &quot;Step 12: Technical &amp; Regulatory Glossary&quot;">​</a></h1><p>This glossary defines every regulatory, machine learning, and software engineering term used across the <strong>21-BIS-Compliance-Engine</strong>.</p><hr><h2 id="_1-regulatory-statutory-terms" tabindex="-1">1. Regulatory &amp; Statutory Terms <a class="header-anchor" href="#_1-regulatory-statutory-terms" aria-label="Permalink to &quot;1. Regulatory &amp; Statutory Terms&quot;">​</a></h2><ul><li><strong>BIS (Bureau of Indian Standards)</strong>: The National Standards Body of India established under the <em>Bureau of Indian Standards Act, 2016</em>, responsible for formulating Indian Standards and administering product certification schemes.</li><li><strong>QCO (Quality Control Order)</strong>: A statutory order issued by an Indian central ministry under Section 16 of the <em>BIS Act, 2016</em>, making compliance with a specified Indian Standard legally mandatory for manufacture, import, distribution, or sale.</li><li><strong>Scheme-I (ISI Mark Certification)</strong>: The premier conformity assessment scheme administered by BIS under which manufacturers are granted a license to use the official Standard Mark (ISI Mark) upon satisfying in-house testing equipment, factory quality control, and laboratory test criteria.</li><li><strong>AIS (Automotive Industry Standards)</strong>: Technical automotive safety standards formulated by the Automotive Industry Standards Committee (AISC) and mandated under the <em>Central Motor Vehicles Rules (CMVR)</em>.</li><li><strong>CMVR Rule 126</strong>: The statutory regulation under the <em>Central Motor Vehicles Rules, 1989</em> requiring manufacturers of motor vehicles and automotive safety components to submit prototypes to authorized testing agencies for Type Approval Certification.</li><li><strong>Homologation</strong>: The formal government approval process certifying that an automotive vehicle or component complies with all mandatory safety, environmental, and performance standards before entering commercial production.</li><li><strong>TAC (Type Approval Certificate)</strong>: An official certificate issued by an accredited agency (ARAI, ICAT, CIRT) confirming that an automotive prototype complies with CMVR and AIS standards.</li><li><strong>COP (Conformity of Production)</strong>: A periodic surveillance audit (mandated under AIS-037) where random production units are drawn from assembly lines to verify ongoing adherence to approved homologation blueprints.</li><li><strong>SIT (Scheme of Inspection and Testing)</strong>: An official regulatory schedule issued by BIS detailing the minimum sampling frequencies, test apparatus, testing procedures, and record-keeping registers required in the factory laboratory.</li><li><strong>NABL (National Accreditation Board for Testing and Calibration Laboratories)</strong>: The constituent board of the Quality Council of India that formally accredits calibration and testing laboratories to international ISO/IEC 17025 standards.</li><li><strong>Manakonline Portal</strong>: The official digital portal operated by the Bureau of Indian Standards for submitting Scheme-I license applications, uploading test reports, and tracking surveillance audits.</li><li><strong>DPIIT</strong>: Department for Promotion of Industry and Internal Trade under the Ministry of Commerce and Industry, which issues QCOs for general consumer goods, cement, and toys.</li><li><strong>MoRTH</strong>: Ministry of Road Transport and Highways, the central government ministry administering the CMVR and AIS automotive standards.</li></ul><hr><h2 id="_2-machine-learning-vector-search-terms" tabindex="-1">2. Machine Learning &amp; Vector Search Terms <a class="header-anchor" href="#_2-machine-learning-vector-search-terms" aria-label="Permalink to &quot;2. Machine Learning &amp; Vector Search Terms&quot;">​</a></h2><ul><li><strong>Dense Vector Embedding</strong>: A fixed-length array of continuous floating-point numbers (here, 384 dimensions) generated by a neural network, encoding semantic meaning such that semantically related concepts are geometrically close in vector space.</li><li><strong>FAISS (Facebook AI Similarity Search)</strong>: An open-source C++ library developed by Meta AI optimized for high-speed similarity search and nearest-neighbor clustering in dense vector collections.</li><li><strong><code>IndexFlatIP</code></strong>: An exact FAISS index that calculates inner products (dot products) between query vectors and corpus vectors. When vectors are unit-normalized ($L_2=1$), inner products are identically equal to cosine similarity.</li><li><strong>Cosine Similarity</strong>: A metric measuring the cosine of the angle between two multi-dimensional vectors, ranging from $-1.0$ (opposite) to $+1.0$ (identical).</li><li><strong>FastEmbed</strong>: A lightweight Python library for generating transformer embeddings via Microsoft ONNX Runtime without requiring PyTorch or CUDA dependencies.</li><li><strong>ONNX (Open Neural Network Exchange)</strong>: An open format representing machine learning models that enables execution via optimized runtimes (ONNX Runtime) across heterogeneous hardware architectures (x86, ARM, CPU, GPU).</li><li><strong>RAG (Retrieval-Augmented Generation)</strong>: An architectural pattern that retrieves relevant, grounded factual documents from an external index to answer user queries, eliminating hallucination risks.</li><li><strong>Domain Guardrail</strong>: A programmatic safety filter combining rule-based heuristics (regex, keyword blacklists) and mathematical vector thresholds to block out-of-domain or non-statutory prompts.</li><li><strong>Joblib</strong>: A set of tools in Python providing lightweight pipelining and disk serialization for Scikit-Learn machine learning estimators.</li></ul><hr><h2 id="_3-web-systems-engineering-terms" tabindex="-1">3. Web &amp; Systems Engineering Terms <a class="header-anchor" href="#_3-web-systems-engineering-terms" aria-label="Permalink to &quot;3. Web &amp; Systems Engineering Terms&quot;">​</a></h2><ul><li><strong>ASGI (Asynchronous Server Gateway Interface)</strong>: The modern Python asynchronous web server specification succeeding WSGI, enabling concurrent handling of HTTP, WebSockets, and background tasks.</li><li><strong>FastAPI</strong>: A modern, high-performance web framework for building REST APIs with Python 3.8+ based on standard Python type hints and Starlette.</li><li><strong>Uvicorn</strong>: A lightning-fast ASGI web server implementation built on <code>uvloop</code> (an ultra-fast libuv event loop) and <code>httptools</code>.</li><li><strong>Pydantic v2</strong>: A data validation and settings management library written in Rust (<code>pydantic-core</code>) that enforces type annotations at runtime and provides automatic serialization.</li><li><strong>CORS (Cross-Origin Resource Sharing)</strong>: An HTTP-header based security mechanism allowing a server to specify which origins are permitted to access its resources from a web browser.</li><li><strong>RFC 4180</strong>: The authoritative Internet engineering specification standardizing the structure, escaping rules, and MIME type (<code>text/csv</code>) of Comma-Separated Values (CSV) files.</li><li><strong>SPA (Single Page Application)</strong>: A web application that loads a single HTML page and dynamically updates content as the user interacts, eliminating full-page browser reloads.</li><li><strong>Vite</strong>: A next-generation frontend build tool featuring an ultra-fast esbuild-powered dev server with instant Hot Module Replacement (HMR) and Rollup-based production bundling.</li><li><strong>Air-Gapped</strong>: A security and operational posture where a computer system or software application is completely isolated from the public internet and external network connections.</li></ul>',11)])])}const h=t(i,[["render",o]]);export{m as __pageData,h as default};
